public static boolean isValidIsbn(String isbn) {
    // Check if the input string is of length 10 (for ISBN-10) or 13 (for ISBN-13)
    if (isbn.length() != 10 && isbn.length() != 13) {
        return false;
    }

    // Check if all characters in the string are digits
    for (int i = 0; i < isbn.length(); i++) {
        if (!Character.isDigit(isbn.charAt(i))) {
            return false;
        }
    }

    // Check if the input string follows the ISBN-10 or ISBN-13 checksum algorithms
    if (isbn.length() == 10) {
        // Check if the input string follows the ISBN-10 checksum algorithm
        int checksum = 0;
        for (int i = 0; i < 9; i++) {
            checksum += (isbn.charAt(i) - '0') * (i + 1);
        }
        return (checksum % 11 == 0);
    } else if (isbn.length() == 13) {
        // Check if the input string follows the ISBN-13 checksum algorithm
        int checksum = 0;
        for (int i = 0; i < 12; i++) {
            checksum += (isbn.charAt(i) - '0') * (i % 2 == 0 ? 1 : 3);
        }
        return (checksum % 10 == 0);
    }

    return false;
}
