public static List<String> getAnagrams(String str) {
    // Create a list to store the anagrams
    List<String> anagrams = new ArrayList<>();

    // Check if the input string is empty
    if (str.isEmpty()) {
        return anagrams;
    }

    // Generate all possible anagrams using recursion
    for (int i = 0; i < str.length(); i++) {
        // Get the character at position i
        char c = str.charAt(i);

        // Remove the character at position i from the input string
        String remaining = str.substring(0, i) + str.substring(i + 1);

        // Generate all possible anagrams for the remaining string
        List<String> remainingAnagrams = getAnagrams(remaining);

        // Add the character at position i to each anagram in the list of remaining anagrams
        for (String anagram : remainingAnagrams) {
            anagrams.add(c + anagram);
        }
    }

    // If the input string has only one character, return a list with the character only
    if (str.length() == 1) {
        return Arrays.asList(str);
    }

