public static List<String> getPalindromicSubstrings(String str) {
    // Create a list to store the palindromic sub-strings
    List<String> palindromes = new ArrayList<>();

    // Check if the input string is empty
    if (str.isEmpty()) {
        return palindromes;
    }

    // Generate all palindromic sub-strings using recursion
    for (int i = 0; i < str.length(); i++) {
        for (int j = i + 1; j <= str.length(); j++) {
            // Get the substring of the input string between position i and position j (inclusive)
            String substr = str.substring(i, j);

            // Check if the substring is palindromic (i.e., the same forwards and backwards)
            if (isPalindrome(substr)) {
                palindromes.add(substr);
            }
        }
    }
    return palindromes;
}

/**
 * Checks if a string is a palindrome (i.e., the same forwards and backwards).
 *
 * @param str The string to check.
 * @return True if the input string is a palindrome, false otherwise.
 */
public static boolean isPalindrome(String str) {
    // Check if the input string is empty
    if (str.isEmpty()) {
        return true;
    }

    // Check if the first and last characters of the string are the same
    if (str.charAt(0) != str.charAt(str.length() - 1)) {
        return false;
    }

    // Recursively check if the remaining string is a palindrome
    return isPalindrome(str.substring(1, str.length() - 1));
}
