    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '.' || c == '_') {
            sb.append(c);
        } else if (c == '\\') {
            if (i == input.length() - 1) {
                break;
            }
            c = input.charAt(++i);
            if (c == 'u') {
                if (i + 4 >= input.length()) {
                    break;
                }
                String hex = input.substring(i + 1, i + 5);
                try {
                    int unescapedChar = Integer.parseInt(hex, 16);
                    sb.append((char) unescapedChar);
                    i = i + 4;
                } catch (NumberFormatException e) {
                    break;
                }
            } else if (c == 'U') {
                if (i + 8 >= input.length()) {
                    break;
