                String hex = input.substring(i + 1, i + 9);
                try {
                    int unescapedChar = Integer.parseInt(hex, 16);
                    sb.append((char) unescapedChar);
                    i = i + 8;
                } catch (NumberFormatException e) {
                    break;
                }
            } else {
