private List<Pair<Integer, Integer>> getMinimalSeparators(Pair<Integer, Integer> vertices, boolean reversed) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();
    for (Pair<Integer, Integer> edge : graph.edgesOf(vertices)) {
        // Check if edge separates the given edge
        if (reversed && edge.getKey() != vertices.getKey()) {
            separators.add(new Pair<>(edge.getKey(), edge.getValue()));
        } else if (!reversed && edge.getKey() != vertices.getValue()) {
