private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the subgraph of graph induced by the given vertices is complete,
    // i.e. a clique.

    // Create a set to store the unique vertices in the subgraph.
    Set<V> subgraphVertices = new HashSet<>();

    // Iterate over the vertices in the subgraph.
    for (V vertex : vertices) {
        // Get the neighbors of the current vertex in the subgraph.
        Set<V> neighbors = graph.getNeighbors(vertex);
        // Add the neighbors to the subgraphVertex set.
