private static ThreadSnapshot readThreadSnapshot(RandomAccessFile reader, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    ByteBuffer buffer = reader.getChannel().map(FileChannel.MapMode.READ_ONLY, reader.getFilePointer(), 16); // 16 is the size of the header
    long startOffset = buffer.getLong();
    long endOffset = buffer.getLong();

    if (endOffset < startOffset) {
        // The file is corrupted, return null
        return null;
    }

    return isSnapshotRequired(startOffset, endOffset, timeRanges) ? importSnapshot(reader, startOffset) : null;
}

private static boolean isSnapshotRequired(long startOffset, long endOffset, List<ProfileAnalyzeTimeRange> timeRanges) {

    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (range.getStart().compareTo(startOffset) <= 0 && range.getEnd().compareTo(endOffset) >= 0) {
            return true;
        }
    }

    return false;
}

private static ThreadSnapshot importSnapshot(RandomAccessFile reader, long startOffset) throws IOException {

    // Import the snapshot, create a ThreadSnapshot instance, and return it
    return new ThreadSnapshot(reader.getChannel().map(FileChannel.MapMode.READ_ONLY, startOffset, endOffset - startOffset));
}

